// src/components/SvgFlow.js
import React, { useRef, useEffect } from "react";
import * as d3 from "d3";

function parseCodeToFlowchart(code = "") {
  const nodes = [];
  const edges = [];

  if (!code || !code.trim()) return { nodes, edges };

  // Parse function declaration
  const fnMatch = code.match(/function\s+(\w+)\s*\(([^)]*)\)/) || code.match(/const\s+(\w+)\s*=\s*\(([^)]*)\)\s*=>/);
  const fnName = fnMatch ? fnMatch[1] : "fn";
  const param = fnMatch ? fnMatch[2].trim() : "";

  // Start node
  nodes.push({ 
    id: "start", 
    label: "Start", 
    type: "terminal",
    shape: "stadium" 
  });

  // Function declaration node
  nodes.push({
    id: "function",
    label: `Function: ${fnName}(${param})`,
    type: "process",
    shape: "rectangle"
  });
  edges.push({ from: "start", to: "function" });

  // Input parameter node
  if (param) {
    nodes.push({ 
      id: "input", 
      label: `Input parameter: ${param}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ from: "function", to: "input" });
  }

  // Decision node for if condition
  const hasCondition = /if\s*\(/.test(code);
  if (hasCondition) {
    const condMatch = code.match(/if\s*\(([^)]+)\)/);
    const condition = condMatch ? condMatch[1].trim() : "condition";
    
    nodes.push({ 
      id: "decision", 
      label: `Check if ${condition}`, 
      type: "decision",
      shape: "diamond" 
    });
    edges.push({ 
      from: param ? "input" : "function", 
      to: "decision" 
    });

    // True path
    const trueLogMatch = code.match(/if\s*\([^{]*\)\s*{([^}]*)}/);
    const trueLog = trueLogMatch ? 
      trueLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "true branch";
    
    nodes.push({ 
      id: "true_process", 
      label: `Print: ${trueLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "true_process", 
      label: "Yes" 
    });

    // False path
    const falseLogMatch = code.match(/else\s*{([^}]*)}/);
    const falseLog = falseLogMatch ? 
      falseLogMatch[1].trim().replace(/console\.log\(|\)/g, '').replace(/["']/g, '') : 
      "false branch";

    nodes.push({ 
      id: "false_process", 
      label: `Print: ${falseLog}`, 
      type: "io",
      shape: "parallelogram" 
    });
    edges.push({ 
      from: "decision", 
      to: "false_process", 
      label: "No" 
    });

    // Connect both paths to end
    edges.push({ from: "true_process", to: "end" });
    edges.push({ from: "false_process", to: "end" });
  } else {
    // If no condition, connect directly to end
    edges.push({ from: param ? "input" : "function", to: "end" });
  }

  // End node
  nodes.push({ 
    id: "end", 
    label: "End", 
    type: "terminal",
    shape: "stadium" 
  });

  return { nodes, edges };
}

function SvgFlow({ graph, code, onNodeClick }) {
  const svgRef = useRef();

  useEffect(() => {
    let g;
    
    // Use graph if provided, otherwise parse code
    if (graph && graph.nodes && graph.nodes.length) {
      g = graph;
      // Normalize the graph - ensure nodes have 'label' property
      g.nodes = g.nodes.map(node => ({
        ...node,
        label: node.label || node.text || 'Unknown',
        shape: node.shape || (
          node.type === 'decision' ? 'diamond' : 
          node.type === 'loop' ? 'diamond' :
          node.type === 'start' ? 'terminal' :
          node.type === 'end' ? 'terminal' :
          node.type === 'input' ? 'parallelogram' :
          node.type === 'output' ? 'parallelogram' :
          node.type === 'function' ? 'rectangle' :
          node.type === 'return' ? 'parallelogram' : 'rectangle'
        )
      }));
    } else if (code) {
      g = parseCodeToFlowchart(code);
    } else {
      g = { nodes: [], edges: [] };
    }
    
    const svgEl = d3.select(svgRef.current);
    svgEl.selectAll("*").remove(); // clear old diagram

    if (!g.nodes || !g.nodes.length) {
      // show placeholder text
      svgEl
        .append("text")
        .attr("x", 20)
        .attr("y", 30)
        .attr("fill", "#6b7280")
        .style("font-size", "14px")
        .text('No flowchart yet — click "Generate Flowchart"');
      return;
    }

    const width = Math.max(600, svgRef.current.parentElement?.clientWidth || 700);
    const nodeWidth = 240;
    const nodeHeight = 60;
    const verticalGap = 100;

    svgEl.attr("width", width).attr("height", g.nodes.length * verticalGap + 150);

    // Simple top-to-bottom layout: center all nodes horizontally
    g.nodes.forEach((n, i) => {
      n.x = width / 2;
      n.y = 60 + i * verticalGap;
      // Ensure label exists
      if (!n.label && n.text) {
        n.label = n.text;
      }
    });

    // markers for arrows
    svgEl
      .append("defs")
      .append("marker")
      .attr("id", "arrow")
      .attr("viewBox", "0 0 10 10")
      .attr("refX", 10)
      .attr("refY", 5)
      .attr("markerWidth", 7)
      .attr("markerHeight", 7)
      .attr("orient", "auto")
      .append("path")
      .attr("d", "M 0 0 L 10 5 L 0 10 z")
      .attr("fill", "#1e293b");

    // draw edges
    const edgeGroup = svgEl.append("g").attr("class", "edges");
    g.edges.forEach((e) => {
      const from = g.nodes.find((n) => n.id === e.from);
      const to = g.nodes.find((n) => n.id === e.to);
      if (!from || !to) return;

      // straight vertical/curved path
      const startX = from.x;
      const startY = from.y + nodeHeight / 2;
      const endX = to.x;
      const endY = to.y - nodeHeight / 2;

      const path = `M ${startX} ${startY} C ${startX} ${(startY + endY) / 2} ${endX} ${(startY + endY) / 2} ${endX} ${endY}`;

      edgeGroup
        .append("path")
        .attr("d", path)
        .attr("fill", "none")
        .attr("stroke", "#1e293b")
        .attr("stroke-width", 2.5)
        .attr("marker-end", "url(#arrow)");

      if (e.label) {
        // label mid-point with background
        const labelBg = edgeGroup
          .append("rect")
          .attr("x", (startX + endX) / 2 - 20)
          .attr("y", (startY + endY) / 2 - 12)
          .attr("width", 40)
          .attr("height", 20)
          .attr("rx", 4)
          .attr("fill", "#ffffff")
          .attr("stroke", "#e2e8f0")
          .attr("stroke-width", 1);
        
        edgeGroup
          .append("text")
          .attr("x", (startX + endX) / 2)
          .attr("y", (startY + endY) / 2 + 2)
          .attr("text-anchor", "middle")
          .attr("fill", "#1e293b")
          .style("font-size", "11px")
          .style("font-weight", "700")
          .text(e.label);
      }
    });

    // draw nodes
    const nodeGroup = svgEl.append("g").attr("class", "nodes");
    const gNodes = nodeGroup.selectAll(".node").data(g.nodes).enter().append("g")
      .attr("class", "node")
      .style("cursor", "pointer")
      .on("click", function(event, d) {
        console.log("Node clicked:", d);
        console.log("onNodeClick function:", onNodeClick);
        console.log("Line number:", d.lineNumber);
        
        // Highlight the node temporarily
        d3.select(this).select("rect, polygon").style("opacity", 0.7);
        setTimeout(() => {
          d3.select(this).select("rect, polygon").style("opacity", 1);
        }, 200);
        
        // Call the callback with line number and node data if provided
        if (onNodeClick) {
          if (d.lineNumber) {
            console.log("Calling onNodeClick with:", d.lineNumber, d);
            onNodeClick(d.lineNumber, d);
          } else {
            console.log("Node has no lineNumber property");
          }
        } else {
          console.log("onNodeClick callback is not defined");
        }
      });

