          .attr("stroke", "#f59e0b")
          .attr("stroke-width", 2.5);
        
        // Wrap text if it's too long
        const text = d.label || d.text || '';
        const words = text.split(' ');
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("fill", "#78350f")
          .style("font-size", "12px")
          .style("font-weight", "600");
        
        if (words.length > 5) {
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.4em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      } else if (d.shape === "stadium" || d.shape === "terminal" || d.type === "start" || d.type === "end") {
        // Terminal shape (rounded rectangle/stadium) for Start/End
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", nodeHeight / 2)
          .attr("ry", nodeHeight / 2)
          .attr("fill", "#dcfce7")
          .attr("stroke", "#16a34a")
          .attr("stroke-width", 2.5);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#14532d")
          .style("font-size", "14px")
          .style("font-weight", "700")
          .text(d.label || d.text || '');
      } else if (d.shape === "parallelogram" || d.type === "io" || d.type === "input" || d.type === "output") {
        // Parallelogram for input/output
        const skewX = 25;
        node
          .append("polygon")
          .attr("points", [
            [x + skewX, y],
            [x + nodeWidth, y],
            [x + nodeWidth - skewX, y + nodeHeight],
            [x, y + nodeHeight],
          ]
            .map((p) => p.join(","))
            .join(" "))
          .attr("fill", "#dbeafe")
          .attr("stroke", "#0284c7")
          .attr("stroke-width", 2.5);

        node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y + 5)
          .attr("text-anchor", "middle")
          .attr("fill", "#0c4a6e")
          .style("font-size", "12px")
          .style("font-weight", "600")
          .text(d.label || d.text || '');
      } else {
        // Rectangle for process steps
        node
          .append("rect")
          .attr("x", x)
          .attr("y", y)
          .attr("width", nodeWidth)
          .attr("height", nodeHeight)
          .attr("rx", 6)
          .attr("fill", "#f3e8ff")
          .attr("stroke", "#9333ea")
          .attr("stroke-width", 2.5);

        // Wrap text for long content
        const text = d.label || d.text || '';
        const maxChars = 40;
        const textElement = node
          .append("text")
          .attr("x", d.x)
          .attr("y", d.y)
          .attr("text-anchor", "middle")
          .attr("fill", "#581c87")
          .style("font-size", "12px")
          .style("font-weight", "600");
        
        if (text.length > maxChars) {
          const words = text.split(' ');
          const mid = Math.ceil(words.length / 2);
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "-0.3em")
            .text(words.slice(0, mid).join(' '));
          textElement
            .append("tspan")
            .attr("x", d.x)
            .attr("dy", "1.2em")
            .text(words.slice(mid).join(' '));
        } else {
          textElement.text(text);
        }
      }
    });
  }, [graph, code]);

  return (
    <div style={{ background: "#fff", padding: "18px", borderRadius: "12px", boxShadow: "0 2px 6px rgba(0,0,0,0.06)", width: "100%", height: "100%", overflow: "auto" }}>
      <svg ref={svgRef} style={{ display: "block" }}></svg>
    </div>
  );
}

export default SvgFlow;
